class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        arr.sort()
        n = len(arr)
        pre = [0]
        for x in arr:
            pre.append(pre[-1] + x)
        best, bestDiff = 0, float('inf')
        for v in range(max(arr) + 1):
            import bisect
            i = bisect.bisect_right(arr, v)
            s = pre[i] + (n - i) * v
            d = abs(s - target)
            if d < bestDiff:
                bestDiff, best = d, v
        return best

