        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (mutated(mid) >= target) hi = mid;
            else lo = mid + 1;
        }
        long long d1 = llabs(mutated(lo) - target);
        long long d2 = llabs(mutated(lo - 1) - target);
        return d2 <= d1 ? (int)(lo - 1) : (int)lo;
