class Solution {
    public int findBestValue(int[] arr, int target) {
        Arrays.sort(arr);
        int n = arr.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + arr[i];
        int lo = 0, hi = arr[n - 1];
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (mutated(arr, pre, mid) >= target) hi = mid;
            else lo = mid + 1;
        }
        long d1 = Math.abs(mutated(arr, pre, lo) - target);
        long d2 = Math.abs(mutated(arr, pre, lo - 1) - target);
        return d2 <= d1 ? lo - 1 : lo;
    }
    private long mutated(int[] arr, long[] pre, int v) {
        int lo = 0, hi = arr.length;
        while (lo < hi) { int m = (lo + hi) / 2; if (arr[m] <= v) lo = m + 1; else hi = m; }
        return pre[lo] + (long)(arr.length - lo) * v;
    }
}

